# Check candidate mode-flag bytes against the stock image and the Z5 CSV.
# Observe only. Do not edit this file after it has run.
import csv
import json
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
CSV = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes.csv'
OUT = ROOT / 'work/out/flag-bytes-f1.json'
BASE = 0x60021020
OWNED_LO = 0x6031E920
OWNED_HI = 0x6031F000  # exclusive; 1760 bytes, HARDWARE-STAGE0-RECORD owned tail
MIRROR_LO = 0x6031EEB0
MIRROR_HI = 0x6031EEE7  # exclusive; 55 bytes 0xa031eeb0..0xa031eee6
RELOC_LO = 0x6031ED00
RELOC_HI = 0x6031EEB0  # exclusive; occupied through 0x6031eeaf
CANDIDATES = [0x6031E924, 0x6031EEE7, 0x6031E91F]

image = IMAGE.read_bytes()
occupied = {}
with CSV.open(encoding='utf-8', newline='') as f:
    for row in csv.DictReader(f):
        occupied[int(row['runtime_address'], 16)] = {
            'source': row['source'],
            'stock': row['stock_byte'],
            'proposed': row['proposed_byte'],
            'section': row.get('section', ''),
            'purpose': row['purpose'],
        }

def image_byte(addr):
    off = addr - BASE
    if off < 0 or off >= len(image):
        return None
    return image[off]

rows = []
for addr in CANDIDATES:
    rec = occupied.get(addr)
    rows.append({
        'addr': f'{addr:08x}',
        'uncached': f'{(addr + 0x40000000):08x}',
        'image': None if image_byte(addr) is None else f'{image_byte(addr):02x}',
        'in_z5': rec is not None,
        'z5': rec,
        'inside_owned': OWNED_LO <= addr < OWNED_HI,
        'inside_mirror': MIRROR_LO <= addr < MIRROR_HI,
        'inside_relocated': RELOC_LO <= addr < RELOC_HI,
    })

# Every Z5 row inside the owned tail, so the chosen byte can be checked against the whole set.
owned_rows = [a for a in occupied if OWNED_LO <= a < OWNED_HI]
chosen = 0x6031EEE7
doc = {
    'owned': [f'{OWNED_LO:08x}', f'{OWNED_HI:08x}'],
    'owned_bytes': OWNED_HI - OWNED_LO,
    'mirror': [f'{MIRROR_LO:08x}', f'{MIRROR_HI - 1:08x}'],
    'relocated_occupied_through': '6031eeaf',
    'z5_rows_in_owned': len(owned_rows),
    'z5_covers_chosen': chosen in occupied,
    'candidates': rows,
    'chosen': {
        'addr': f'{chosen:08x}',
        'uncached': 'a031eee7',
        'why': 'First byte after the 55-byte mirror, inside the owned tail, stock 0xFF, absent from the Z5 CSV and from the relocated block.',
    },
}
ok = (
    image_byte(chosen) == 0xFF
    and chosen not in occupied
    and OWNED_LO <= chosen < OWNED_HI
    and not (MIRROR_LO <= chosen < MIRROR_HI)
    and not (RELOC_LO <= chosen < RELOC_HI)
    and 0x6031E91F not in range(OWNED_LO, OWNED_HI)
)
doc['ok'] = ok
OUT.write_text(json.dumps(doc, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'ok': ok, 'chosen': doc['chosen']['addr'], 'z5_rows_in_owned': len(owned_rows)}))
if not ok:
    raise SystemExit(1)
